  /* ============================================================
     8. 第五幕 · 计算机：编码链 + 粒子溶解 (纯前端原生解构 · 零延迟无外部依赖)
  ============================================================ */
  const encodeInput = $("#encodeInput");
  const encodeRun = $("#encodeRun");
  const encChar = $("#encChar"), encUnicode = $("#encUnicode"), encBinary = $("#encBinary"), encData = $("#encData");
  const encodeLayers = $$(".encode-layer");
  const encodeCanvas = $("#encodeCanvas");
  const encodeStatusHint = $("#encodeStatusHint");
  const ecx = encodeCanvas.getContext("2d");

  function isSingleHanzi(str) {
    if (!str) return false;
    const trimmed = str.trim();
    // 匹配单汉字：CJK 统一表意文字及扩展区（简体与繁体）
    return /^[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff\u{20000}-\u{2ceaf}\u{2ceb0}-\u{2ebe0}]$/u.test(trimmed);
  }

  // 本地标准化编码解析算法 (严格遵循 Unicode 标准与 RFC 3629 UTF-8 变长字节规范)
  function localEncode(raw) {
    const trimmed = (raw || "").trim();
    if (!isSingleHanzi(trimmed)) {
      return {
        "字符": "请输入正确的汉字",
        "Unicode": "请输入正确的汉字",
        "二进制": "请输入正确的汉字",
        "数据": "请输入正确的汉字"
      };
    }
    const cp = trimmed.codePointAt(0);
    const bytes = toUTF8(cp);
    const binStr = cp.toString(2).padStart(16, "0");
    return {
      "字符": trimmed,
      "Unicode": "U+" + cp.toString(16).toUpperCase().padStart(4, "0") + " · " + cp,
      "二进制": group4(binStr),
      "数据": bytes.map(hexByte).join(" ")
    };
  }

  function lightLayers(seq) {
    encodeLayers.forEach((l, i) => l.classList.toggle("lit", i === seq));
  }

  let currentBinData = "0101 0110 1111 1101";

  function applyEncodeResult(result, shouldAnimate = true) {
    const isError = result["字符"] === "请输入正确的汉字" ||
                    result["Unicode"] === "请输入正确的汉字" ||
                    result["二进制"] === "请输入正确的汉字" ||
                    result["数据"] === "请输入正确的汉字";

    encChar.textContent = result["字符"] || "请输入正确的汉字";
    encUnicode.textContent = result["Unicode"] || "请输入正确的汉字";
    encBinary.textContent = result["二进制"] || "请输入正确的汉字";
    encData.textContent = result["数据"] || "请输入正确的汉字";

    encodeLayers.forEach((l) => {
      l.classList.toggle("is-error", isError);
    });

    if (encodeStatusHint) {
      encodeStatusHint.classList.toggle("is-error", isError);
      encodeStatusHint.classList.remove("is-loading");
      if (isError) {
        encodeStatusHint.textContent = "⚠ 请输入正确的单个汉字（支持简体或繁体中文）";
      } else {
        encodeStatusHint.textContent = "✓ 标准编码解构完成 [字符 → Unicode → 二进制 → 数据]";
      }
    }

    if (isError) {
      drawEncodeError();
    } else {
      currentBinData = result["二进制"] || "0101 0110 1111 1101";
      if (shouldAnimate) {
        [0, 1, 2, 3].forEach((i) => setTimeout(() => lightLayers(i), i * 260));
        setTimeout(() => lightLayers(-1), 1200);
        dissolveChar(result["字符"]);
      }
    }
  }

  function drawEncodeError() {
    cancelAnimationFrame(encAnim);
    const W = encodeCanvas.width, H = encodeCanvas.height;
    ecx.clearRect(0, 0, W, H);

    ecx.font = "600 48px serif";
    ecx.fillStyle = "#e07a5f";
    ecx.textAlign = "center";
    ecx.textBaseline = "middle";
    ecx.fillText("⚠", 120, H / 2);

    ecx.font = "500 18px sans-serif";
    ecx.fillStyle = "#e07a5f";
    ecx.textAlign = "left";
    ecx.fillText("请输入正确的汉字（支持简体或繁体中文单个字符）", 180, H / 2 - 12);

    ecx.font = "13px monospace";
    ecx.fillStyle = "rgba(233, 228, 216, 0.55)";
    ecx.fillText("非汉字字符输入时，[字符 / Unicode / 二进制 / 数据] 统一提示报错", 180, H / 2 + 18);
  }

  /* 粒子：字形 → 数据流 */
  let encParticles = [];
  let encAnim = 0, encStart = 0;
  function dissolveChar(ch) {
    cancelAnimationFrame(encAnim);
    playSFX("decompose", 0.85);
    const off = document.createElement("canvas");
    off.width = off.height = 120;
    const o = off.getContext("2d");
    o.fillStyle = "#fff";
    o.font = "600 104px serif";
    o.textAlign = "center"; o.textBaseline = "middle";
    o.fillText(ch, 60, 60);
    const data = o.getImageData(0, 0, 120, 120).data;
    encParticles = [];
    const step = 3;
    for (let y = 0; y < 120; y += step) {
      for (let x = 0; x < 120; x += step) {
        if (data[(y * 120 + x) * 4 + 3] > 90) {
          encParticles.push({
            x: 70 + x * 1.5, y: 20 + y * 1.5,
            ox: 70 + x * 1.5, oy: 20 + y * 1.5,
            bit: Math.random() < 0.5 ? "0" : "1",
            delay: Math.random() * 0.4,
          });
        }
      }
    }
    encStart = performance.now();
    drawEncode(ch);
  }

  function drawEncode(ch) {
    const W = encodeCanvas.width, H = encodeCanvas.height;
    const t = (performance.now() - encStart) / 2400; // 0..1
    ecx.clearRect(0, 0, W, H);

    // 数据流列（右侧二进制流，取当前汉字真实二进制）
    const cleanBin = currentBinData.replace(/\s+/g, "");
    const binStr = Array.from((cleanBin + cleanBin + cleanBin).slice(0, 24));
    ecx.font = "13px monospace";
    ecx.fillStyle = "rgba(114,214,208,.9)";
    for (let i = 0; i < binStr.length; i++) {
      const row = Math.floor(i / 4);
      const pos = Math.max(0, (t * 1.2) - row * 0.14);
      ecx.globalAlpha = Math.max(0, Math.min(1, pos));
      ecx.fillText(binStr[i], W - 150 + (i % 4) * 11, 60 + row * 18);
    }

    // 粒子：从左（字形）向右（数据）漂移
    for (const p of encParticles) {
      const pt = Math.max(0, Math.min(1, (t * 1.4) - p.delay * 0.3));
      const ex = 70 + (W - 240 - 70) * easeOut(pt);
      const x = p.ox + (ex - p.ox) * easeOut(pt);
      const y = p.oy + Math.sin(pt * 5 + p.oy) * 6;
      const alpha = pt < 0.6 ? 0.9 : (1 - pt) * 2.2;
      ecx.globalAlpha = Math.max(0, alpha);
      ecx.fillStyle = pt > 0.55 ? "#72D6D0" : "#E9E4D8";
      ecx.fillRect(x, y, 2, 2);
    }
    ecx.globalAlpha = 1;

    if (t < 1) encAnim = requestAnimationFrame(() => drawEncode(ch));
    else {
      // 定格为数据流
      encAnim = requestAnimationFrame(() => { /* 保持末帧 */ });
    }
  }
  const easeOut = (t) => 1 - Math.pow(1 - t, 3);

  function runEncode() {
    const rawVal = (encodeInput.value || "").trim();
    const result = localEncode(rawVal);
    applyEncodeResult(result);
  }

  encodeRun.addEventListener("click", () => {
    if (document.activeElement === encodeInput) encodeInput.blur();
    runEncode();
    setTimeout(() => {
      const lab = document.querySelector(".encode-lab");
      if (lab) lab.scrollIntoView({ behavior: "smooth", block: "center" });
    }, 150);
  });
  encodeInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      if (document.activeElement === encodeInput) encodeInput.blur();
      runEncode();
      setTimeout(() => {
        const lab = document.querySelector(".encode-lab");
        if (lab) lab.scrollIntoView({ behavior: "smooth", block: "center" });
      }, 150);
    }
  });
  encodeInput.addEventListener("input", () => playSFX("keyboard", 0.6));
  encodeInput.addEventListener("blur", () => {
    [100, 300].forEach((delay) => {
      setTimeout(() => {
        const lab = document.querySelector(".encode-lab");
        if (lab) {
          const rect = lab.getBoundingClientRect();
          if (rect.top < -50 || rect.bottom > window.innerHeight + 150) {
            lab.scrollIntoView({ behavior: "smooth", block: "center" });
          }
        }
      }, delay);
    });
  });

  // 初始状态仅显示静态字形与编码，不自动播放粒子动画与音效，等待用户主动点击「拆解」
  function initEncodeCanvas() {
    applyEncodeResult({
      "字符": "国",
      "Unicode": "U+56FD · 22269",
      "二进制": "0101 0110 1111 1101",
      "数据": "E5 9B BD"
    }, false);
    const W = encodeCanvas.width, H = encodeCanvas.height;
    ecx.clearRect(0, 0, W, H);
    ecx.font = "600 100px serif";
    ecx.fillStyle = "#E9E4D8";
    ecx.textAlign = "center";
    ecx.textBaseline = "middle";
    ecx.fillText("国", 130, H / 2);
    
    // 提示文字
    ecx.font = "14px sans-serif";
    ecx.fillStyle = "rgba(114, 214, 208, 0.7)";
    ecx.textAlign = "left";
    ecx.fillText("👈 点击上方「拆解」按钮，观察汉字如何实时粒子化分解为 0 / 1 二进制数据流", 250, H / 2 - 8);
    ecx.font = "12px monospace";
    ecx.fillStyle = "rgba(255, 255, 255, 0.35)";
    ecx.fillText("UTF-8: E5 9B BD  |  UNICODE: U+56FD  |  TOKEN ID: 7654", 250, H / 2 + 20);
  }
  initEncodeCanvas();

  /* ============================================================
     9. 第六幕 · 芯片：Intel Core Ultra vs 华为昇腾 910B 汉字物理运算动手实验台
  ============================================================ */
  const labPanelIntel = $("#labPanelIntel");
  const labPanelAscend = $("#labPanelAscend");

  // Intel CPU 实验控件
  const btnLoadRax = $("#btnLoadRax");
  const btnShrqRax = $("#btnShrqRax");
  const btnL3Probe = $("#btnL3Probe");
  const regSlots = $("#regSlots");
  const regNote = $("#regNote");
  const regBytes = $$(".reg-byte", regSlots);
  const regStatusTag = $("#regStatusTag");
  const cpuPhaseTitle = $("#cpuPhaseTitle");
  const cpuAsmCode = $("#cpuAsmCode");
  const cpuMeaningText = $("#cpuMeaningText");

  // 华为昇腾 NPU 实验控件
  const btnHbmPull = $("#btnHbmPull");
  const btnCubeMatmul = $("#btnCubeMatmul");
  const btnVectorSoftmax = $("#btnVectorSoftmax");
  const cubeSemanticGrid = $("#cubeSemanticGrid");
  const semanticCells = $$(".semantic-cell", cubeSemanticGrid);
  const cubeNote = $("#cubeNote");
  const cubeStatusTag = $("#cubeStatusTag");
  const npuPhaseTitle = $("#npuPhaseTitle");
  const npuAsmCode = $("#npuAsmCode");
  const npuMeaningText = $("#npuMeaningText");

  // Intel CPU 实验交互逻辑
  if (btnLoadRax) {
    btnLoadRax.addEventListener("click", () => {
      [btnLoadRax, btnShrqRax, btnL3Probe].forEach(b => b && b.classList.remove("is-active"));
      btnLoadRax.classList.add("is-active");
      regBytes.forEach((b, i) => {
        b.classList.remove("pulse-active");
        if (i < 5) { b.textContent = "00"; b.classList.remove("is-filled"); }
      });
      if (regBytes[5]) { regBytes[5].textContent = "E5"; regBytes[5].classList.add("is-filled", "pulse-active"); }
      if (regBytes[6]) { regBytes[6].textContent = "9B"; regBytes[6].classList.add("is-filled", "pulse-active"); }
      if (regBytes[7]) { regBytes[7].textContent = "BD"; regBytes[7].classList.add("is-filled", "pulse-active"); }
      if (regStatusTag) regStatusTag.textContent = "已装入「国」字 24位 机器码";
      if (regNote) regNote.textContent = "UTF-8 机器码 [E5 9B BD] 载入 RAX 寄存器低 24 位";
      if (cpuPhaseTitle) cpuPhaseTitle.textContent = "【计算意义 · 载入寄存器】";
      if (cpuAsmCode) cpuAsmCode.textContent = "MOVQ RAX, 0x0000000000E59BBD";
      if (cpuMeaningText) {
        cpuMeaningText.textContent = "将「国」的 3 字节机器码瞬间读入 CPU 最核心的物理寄存器 RAX，便于高速计算。";
      }
    });
  }

  if (btnShrqRax) {
    btnShrqRax.addEventListener("click", () => {
      [btnLoadRax, btnShrqRax, btnL3Probe].forEach(b => b && b.classList.remove("is-active"));
      btnShrqRax.classList.add("is-active");
      regBytes.forEach((b) => b.classList.add("pulse-active"));
      if (regBytes[5]) { regBytes[5].textContent = "00"; regBytes[5].classList.remove("is-filled"); }
      if (regBytes[6]) { regBytes[6].textContent = "E5"; regBytes[6].classList.add("is-filled"); }
      if (regBytes[7]) { regBytes[7].textContent = "9B"; regBytes[7].classList.add("is-filled"); }
      if (regStatusTag) regStatusTag.textContent = "已向右逻辑移位 8 位 (1个字节)";
      if (regNote) regNote.textContent = "SHRQ RAX, 8 移位完毕：RAX 变为 [0x000000000000E59B]，剥离出中间字节与前缀标志位。";
      if (cpuPhaseTitle) cpuPhaseTitle.textContent = "【计算意义 · 逻辑右移对齐】";
      if (cpuAsmCode) cpuAsmCode.textContent = "SHRQ RAX, 0x08";
      if (cpuMeaningText) {
        cpuMeaningText.textContent = "寄存器向右移位 8 位分离编码字节，供 ALU 快速校验 UTF-8 标志位与合法性。";
      }
    });
  }

  if (btnL3Probe) {
    btnL3Probe.addEventListener("click", () => {
      [btnLoadRax, btnShrqRax, btnL3Probe].forEach(b => b && b.classList.remove("is-active"));
      btnL3Probe.classList.add("is-active");
      regBytes.forEach((b) => b.classList.add("pulse-active"));
      if (regStatusTag) regStatusTag.textContent = "L3 高速缓存命中 100% (TAG_MATCH)";
      if (regNote) regNote.textContent = "L3 高速缓存探针命中：Ring Bus 环形总线高速传输，延迟仅 11.2ns。";
      if (cpuPhaseTitle) cpuPhaseTitle.textContent = "【计算意义 · 片上缓存检索】";
      if (cpuAsmCode) cpuAsmCode.textContent = "RING_BUS_PROBE: L3_HIT (11.2 ns)";
      if (cpuMeaningText) {
        cpuMeaningText.textContent = "通过片上环形总线检索 24MB 高速 L3 缓存，11.2ns 内极速调出字模点阵笔画。";
      }
    });
  }

  // 华为昇腾 NPU 实验交互逻辑
  if (btnHbmPull) {
    btnHbmPull.addEventListener("click", () => {
      [btnHbmPull, btnCubeMatmul, btnVectorSoftmax].forEach(b => b && b.classList.remove("is-active"));
      btnHbmPull.classList.add("is-active");
      semanticCells.forEach((c) => c.classList.remove("active"));
      if (cubeStatusTag) cubeStatusTag.textContent = "HBM2E 总线 1.2TB/s 传输完毕";
      if (cubeNote) cubeNote.textContent = "HBM2E 显存拉取完毕：「国」字 4096 维浮点张量载入片上高速 SRAM。";
      if (npuPhaseTitle) npuPhaseTitle.textContent = "【计算意义 · 语义升维】";
      if (npuAsmCode) npuAsmCode.textContent = "acl::EmbeddingLookup(TokenID=7654, Dim=4096)";
      if (npuMeaningText) {
        npuMeaningText.textContent = "从显存拉取「国」字的 4096 维连续浮点张量，将离散字符化为高维语义空间坐标。";
      }
    });
  }

  if (btnCubeMatmul) {
    btnCubeMatmul.addEventListener("click", () => {
      [btnHbmPull, btnCubeMatmul, btnVectorSoftmax].forEach(b => b && b.classList.remove("is-active"));
      btnCubeMatmul.classList.add("is-active");
      semanticCells.forEach((c) => c.classList.add("active"));
      if (cubeStatusTag) cubeStatusTag.textContent = "3D Cube 阵列 318.6 TFLOPS 计算中";
      if (cubeNote) cubeNote.textContent = "DaVinci 3D Cube 全速运转：单周期并行完成 4096 次乘加 (MACs)。";
      if (npuPhaseTitle) npuPhaseTitle.textContent = "【计算意义 · 张量矩阵乘法】";
      if (npuAsmCode) npuAsmCode.textContent = "cube::MatMul(Tensor_Q[1, 64], Tensor_K_T[64, 4096])";
      if (npuMeaningText) {
        npuMeaningText.textContent = "3D Cube 阵列执行 Query × Key^T 矩阵乘，单周期并行计算「国」与上下文词汇的语义关联度。";
      }
    });
  }

  if (btnVectorSoftmax) {
    btnVectorSoftmax.addEventListener("click", () => {
      [btnHbmPull, btnCubeMatmul, btnVectorSoftmax].forEach(b => b && b.classList.remove("is-active"));
      btnVectorSoftmax.classList.add("is-active");
      semanticCells.forEach((c) => {
        const word = c.dataset.word;
        c.classList.toggle("active", word === "家" || word === "中");
      });
      if (cubeStatusTag) cubeStatusTag.textContent = "Softmax 归一化完成 · 锁定「国家」(98.2%)";
      if (cubeNote) cubeNote.textContent = "Vector 矢量单元完成 Softmax 归一化：将无界分值收敛为置信度分布。";
      if (npuPhaseTitle) npuPhaseTitle.textContent = "【计算意义 · 概率归一化】";
      if (npuAsmCode) npuAsmCode.textContent = "vector::Softmax(Score_Matrix, FP16)";
      if (npuMeaningText) {
        npuMeaningText.textContent = "Vector 单元执行指数 Softmax 归一化，以 98.2% 置信度锁定关联词「家」（国家）。";
      }
    });
  }

  // 芯片三段文案随进入视口依次浮现
  const chipLines = $(".chip-lines");
  if (chipLines) {
    const chipLinesObs = new IntersectionObserver((entries) => {
      entries.forEach((en) => { if (en.isIntersecting) { chipLines.classList.add("in"); chipLinesObs.disconnect(); } });
    }, { threshold: 0.4 });
    chipLinesObs.observe(chipLines);
  }

  /* ============================================================
     10. 第七幕 · 人工智能：左侧特征提取 ➔ 右侧 Transformer FFN 与 因果生成
  ============================================================ */
  const stepGlyph = $("#stepGlyph");
  const stepToken = $("#stepToken");
  const stepEncode = $("#stepEncode");
  const stepData = $("#stepData");
  const blockEncoder = $("#blockEncoder");
  const blockDecoder = $("#blockDecoder");
  const head1 = $("#head1");
  const head2 = $("#head2");
  const head3 = $("#head3");
  const decoderStatus = $("#decoderStatus");
  const vocabItems = $$(".vocab-item");

  // FFN Lab 交互控件
  const ffnTokBtns = $$(".ffn-tok-btn");
  const btnPulseFFN = $("#btnPulseFFN");
  const ffnSvg = $("#ffnSvg");
  const neuronNodes = $$(".neuron-node", ffnSvg);
  const synLines = $$(".syn-line", ffnSvg);
  const ffnProbeText = $("#ffnProbeText");

  // Decoder Workbench 交互控件
  const decActiveChip = $("#decActiveChip");
  const decCandBtns = $$(".dec-cand-btn");

  // 针对不同汉字的基础特征激活拓扑模型 (每字拥有不同的语义神经通路，叠加随机波动)
  const charNeuronProfiles = {
    "国": {
      name: "国家 / 疆域 / 社稷",
      layers: {
        0: [0, 2],       // x1 (疆域主权), x3 (政治体系)
        1: [0, 1, 3],    // h1, h2, h4
        2: [0, 1, 2],    // g1 (华夏文明), g2 (天下疆域), g3 (政权社稷)
        3: [0, 1]        // y1 (中国), y2 (国家)
      }
    },
    "家": {
      name: "家室 / 血缘 / 归属",
      layers: {
        0: [1, 2],       // x2 (血缘伦理), x3 (居住聚落)
        1: [1, 2],       // h2, h3
        2: [1, 3],       // g2 (天下万姓), g4 (家国黎民)
        3: [1, 2]        // y2 (国家), y3 (国土/家园)
      }
    },
    "中": {
      name: "中心 / 轴心 / 正统",
      layers: {
        0: [0, 1],       // x1 (中心定位), x2 (华夏正朔)
        1: [0, 2, 3],    // h1, h3, h4
        2: [0, 2],       // g1 (华夏文明), g3 (政权社稷)
        3: [0, 2]        // y1 (中国), y3 (天下)
      }
    }
  };

  // 生成特定字的前向激活拓扑 (叠加随机 Dropout / 神经元自发扰动)
  function getActiveTopology(char) {
    const profile = charNeuronProfiles[char] || charNeuronProfiles["国"];
    const activeSet = { 0: new Set(), 1: new Set(), 2: new Set(), 3: new Set() };

    for (let l = 0; l <= 3; l++) {
      profile.layers[l].forEach(idx => activeSet[l].add(idx));
      // 随机扰动：有 40% 几率随机激活或抑制某额外神经元，形成生物神经网络般的自适应波动
      const maxNodes = (l === 0 || l === 3) ? 3 : 4;
      if (Math.random() < 0.45) {
        const randIdx = Math.floor(Math.random() * maxNodes);
        if (activeSet[l].has(randIdx) && activeSet[l].size > 1) {
          activeSet[l].delete(randIdx);
        } else {
          activeSet[l].add(randIdx);
        }
      }
    }
    return { profile, activeSet };
  }

  // FFN 脉冲级联传播函数
  let isPulsing = false;
  function triggerFFNPulse(tokChar = "国") {
    if (isPulsing) return;
    isPulsing = true;

    const { profile, activeSet } = getActiveTopology(tokChar);

    // 全部复位
    neuronNodes.forEach(n => n.classList.remove("is-firing", "is-dimmed"));
    synLines.forEach(l => l.classList.remove("is-pulsing", "is-dimmed"));

    // 0ms: Layer 0 输入层激发
    neuronNodes.forEach(n => {
      const l = parseInt(n.dataset.layer, 10);
      const idx = parseInt(n.dataset.idx, 10);
      if (l === 0) {
        if (activeSet[0].has(idx)) {
          n.classList.add("is-firing");
        } else {
          n.classList.add("is-dimmed");
        }
      }
    });
    if (ffnProbeText) {
      const l0Active = [...activeSet[0]].map(i => `x${i+1}`).join(",");
      ffnProbeText.textContent = `⚡ [L0 输入] 载入「${tokChar}」：点亮 [${l0Active}]，启动专属特征通路传播...`;
    }

    // 180ms: Layer 0 -> Layer 1 突触传输
    setTimeout(() => {
      synLines.forEach(line => {
        let isPulsingLine = false;
        activeSet[0].forEach(fromIdx => {
          activeSet[1].forEach(toIdx => {
            if (line.classList.contains(`l0-${fromIdx}`) && line.classList.contains(`l1-${toIdx}`)) {
              isPulsingLine = true;
            }
          });
        });
        if (isPulsingLine) {
          line.classList.add("is-pulsing");
        } else if (line.classList.contains("l0-0") || line.classList.contains("l0-1") || line.classList.contains("l0-2")) {
          line.classList.add("is-dimmed");
        }
      });
    }, 180);

    // 380ms: Layer 1 隐藏层神经元点火
    setTimeout(() => {
      synLines.forEach(l => l.classList.remove("is-pulsing", "is-dimmed"));
      neuronNodes.forEach(n => {
        const l = parseInt(n.dataset.layer, 10);
        const idx = parseInt(n.dataset.idx, 10);
        if (l === 1) {
          if (activeSet[1].has(idx)) {
            n.classList.add("is-firing");
          } else {
            n.classList.add("is-dimmed");
          }
        }
      });
      if (ffnProbeText) {
        const l1Active = [...activeSet[1]].map(i => `h${i+1}`).join(",");
        ffnProbeText.textContent = `⚡ [L1 隐层1] GELU 激活：点亮 [${l1Active}]，非线性矩阵映射...`;
      }
    }, 380);

    // 580ms: Layer 1 -> Layer 2 突触传输
    setTimeout(() => {
      synLines.forEach(line => {
        let isPulsingLine = false;
        activeSet[1].forEach(fromIdx => {
          activeSet[2].forEach(toIdx => {
            if (line.classList.contains(`l1-${fromIdx}`) && line.classList.contains(`l2-${toIdx}`)) {
              isPulsingLine = true;
            }
          });
        });
        if (isPulsingLine) {
          line.classList.add("is-pulsing");
        } else if (line.classList.contains("l1-0") || line.classList.contains("l1-1") || line.classList.contains("l1-2") || line.classList.contains("l1-3")) {
          line.classList.add("is-dimmed");
        }
      });
    }, 580);

    // 780ms: Layer 2 隐藏层神经元深度抽象点火
    setTimeout(() => {
      synLines.forEach(l => l.classList.remove("is-pulsing", "is-dimmed"));
      neuronNodes.forEach(n => {
        const l = parseInt(n.dataset.layer, 10);
        const idx = parseInt(n.dataset.idx, 10);
        if (l === 2) {
          if (activeSet[2].has(idx)) {
            n.classList.add("is-firing");
          } else {
            n.classList.add("is-dimmed");
          }
        }
      });
      if (ffnProbeText) {
        const l2Active = [...activeSet[2]].map(i => `g${i+1}`).join(",");
        ffnProbeText.textContent = `⚡ [L2 隐层2] 高阶抽象：点亮 [${l2Active}]，文明深层认知收敛...`;
      }
    }, 780);

    // 980ms: Layer 2 -> Layer 3 突触传输
    setTimeout(() => {
      synLines.forEach(line => {
        let isPulsingLine = false;
        activeSet[2].forEach(fromIdx => {
          activeSet[3].forEach(toIdx => {
            if (line.classList.contains(`l2-${fromIdx}`) && line.classList.contains(`l3-${toIdx}`)) {
              isPulsingLine = true;
            }
          });
        });
        if (isPulsingLine) {
          line.classList.add("is-pulsing");
        } else if (line.classList.contains("l2-0") || line.classList.contains("l2-1") || line.classList.contains("l2-2") || line.classList.contains("l2-3")) {
          line.classList.add("is-dimmed");
        }
      });
    }, 980);

    // 1180ms: Layer 3 输出表征生成
    setTimeout(() => {
      synLines.forEach(l => l.classList.remove("is-pulsing", "is-dimmed"));
      neuronNodes.forEach(n => {
        const l = parseInt(n.dataset.layer, 10);
        const idx = parseInt(n.dataset.idx, 10);
        if (l === 3) {
          if (activeSet[3].has(idx)) {
            n.classList.add("is-firing");
          } else {
            n.classList.add("is-dimmed");
          }
        }
      });
      if (ffnProbeText) {
        const l3Active = [...activeSet[3]].map(i => `y${i+1}`).join(",");
        ffnProbeText.textContent = `✨ [L3 输出] 「${tokChar}」前向计算收敛：节点 [${l3Active}] 高光响应，深层特征提取完成。`;
      }
    }, 1180);

    // 2200ms: 结束复位
    setTimeout(() => {
      neuronNodes.forEach(n => n.classList.remove("is-firing", "is-dimmed"));
      synLines.forEach(l => l.classList.remove("is-pulsing", "is-dimmed"));
      isPulsing = false;
    }, 2200);
  }

  // 绑定 FFN 脉冲按键
  if (btnPulseFFN) {
    btnPulseFFN.addEventListener("click", () => {
      const activeTokBtn = $(".ffn-tok-btn.is-active");
      const tok = activeTokBtn ? activeTokBtn.dataset.tok : "国";
      triggerFFNPulse(tok);
    });
  }

  // 绑定 FFN 激励字切换
  ffnTokBtns.forEach(btn => {
    btn.addEventListener("click", () => {
      ffnTokBtns.forEach(b => b.classList.remove("is-active"));
      btn.classList.add("is-active");
      const tok = btn.dataset.tok;
      triggerFFNPulse(tok);
    });
  });

  // 神经元悬停探针
  neuronNodes.forEach(node => {
    node.addEventListener("mouseenter", () => {
      const l = parseInt(node.dataset.layer, 10);
      const idx = parseInt(node.dataset.idx, 10);
      const name = node.dataset.name || `节点 L${l}_${idx}`;
      const val = node.dataset.val || "0.90";
      if (ffnProbeText) {
        ffnProbeText.textContent = `🔍 探针响应：${name} · 权重响应度 ${val} · GELU 激活就绪`;
      }
      node.classList.add("is-firing");
    });
    node.addEventListener("mouseleave", () => {
      if (!isPulsing) {
        node.classList.remove("is-firing");
        const activeTokBtn = $(".ffn-tok-btn.is-active");
        const tok = activeTokBtn ? activeTokBtn.dataset.tok : "国";
        if (ffnProbeText) {
          ffnProbeText.textContent = `悬停或点击任意神经元节点，可探查「${tok}」前向激活度与权重响应`;
        }
      }
    });
  });

  // Decoder 自回归候选点击交互
  decCandBtns.forEach(btn => {
    btn.addEventListener("click", () => {
      decCandBtns.forEach(b => b.classList.remove("is-active"));
      btn.classList.add("is-active");
      const char = btn.dataset.char;
      const prob = btn.dataset.prob;

      if (decActiveChip) {
        decActiveChip.textContent = char;
        decActiveChip.classList.add("pulse-chip");
        setTimeout(() => decActiveChip.classList.remove("pulse-chip"), 600);
      }

      if (decoderStatus) {
        decoderStatus.textContent = `自回归因果解码：锁定「${char}」，时序流扩展为「中 ➔ 国 ➔ ${char}」，置信度 ${prob} ✓`;
      }

      // 同步高亮下方对应词表条目
      vocabItems.forEach(v => {
        const w = v.dataset.word || "";
        if (w.includes(char)) {
          v.classList.add("is-highlight");
        } else {
          v.classList.remove("is-highlight");
        }
      });
    });
  });

  // 叙事推演循环
  let aiCycleTimer = null;
  let aiCycleStart = 0;
  const cycleDuration = 9600; // 自动推演叙事周期 9.6s

  const stepsList = [stepGlyph, stepToken, stepEncode, stepData];
  const headsList = [head1, head2, head3];

  let lastFFNPulseCycle = -1;

  function runAiStep(elapsed, cycleIndex) {
    // 0.0s - 2.8s: 左侧特征提取 01 -> 02 -> 03 -> 04 顺次流转
    if (stepGlyph) stepGlyph.classList.toggle("is-active", elapsed >= 0 && elapsed < 9200);
    if (stepToken) stepToken.classList.toggle("is-active", elapsed >= 700 && elapsed < 9200);
    if (stepEncode) stepEncode.classList.toggle("is-active", elapsed >= 1400 && elapsed < 9200);
    if (stepData) stepData.classList.toggle("is-active", elapsed >= 2100 && elapsed < 9200);

    // 2.8s - 5.2s: 右侧 Transformer ENCODER 核心机制（多头注意力 + FFN 神经元脉冲）
    if (blockEncoder) {
      blockEncoder.classList.toggle("lit", elapsed >= 2800 && elapsed < 9200);
    }
    if (head1) head1.classList.toggle("lit", elapsed >= 3200 && elapsed < 9200);
    if (head2) head2.classList.toggle("lit", elapsed >= 3600 && elapsed < 9200);
    if (head3) head3.classList.toggle("lit", elapsed >= 4000 && elapsed < 9200);

    // 周期内 4200ms 自动触发一次 FFN 前向脉冲
    if (elapsed >= 4200 && elapsed < 6500 && lastFFNPulseCycle !== cycleIndex) {
      lastFFNPulseCycle = cycleIndex;
      triggerFFNPulse("国");
    }

    // 5.2s - 7.0s: DECODER 因果解码生成流
    if (blockDecoder) {
      blockDecoder.classList.toggle("lit", elapsed >= 5200 && elapsed < 9200);
    }

    if (decoderStatus && !isPulsing) {
      if (elapsed >= 5200 && elapsed < 9200) {
        decoderStatus.textContent = "跨注意力融合完成 · 自回归高光生成「家」，锁定「国家」✓";
      } else if (elapsed < 5200) {
        decoderStatus.textContent = "计算自回归后验状态向量 H...";
      }
    }

    // 6.6s ~ 9.2s: 候选词表自上而下展开，国家金色耀眼光辉锁定
    const vocabDelay = [6600, 7100, 7600, 8100, 8600];
    vocabItems.forEach((item, i) => {
      const t = vocabDelay[i] || 6600;
      item.classList.toggle("lit", elapsed >= t && elapsed < 9200);
    });
  }

  function startAiCycle() {
    const now = performance.now();
    aiCycleStart = now;

    function frame() {
      const current = performance.now();
      const totalElapsed = current - aiCycleStart;
      const cycleIndex = Math.floor(totalElapsed / cycleDuration);
      const elapsed = totalElapsed % cycleDuration;
      runAiStep(elapsed, cycleIndex);
      aiCycleTimer = requestAnimationFrame(frame);
    }
    cancelAnimationFrame(aiCycleTimer);
    aiCycleTimer = requestAnimationFrame(frame);
  }

